head.script:
scwin.onpageload = function() {
    localStorage.removeItem("log");
    windowContainer1.createWindow("music", "", "windoContainer_createWindow_WEFF-585_(WSQ-3939)_sub1_auto.xml", "page001", "P0001", "existWindow", "", "", "", "", "wframe")
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    //windowContainer1.createWindow( "music" , "" , "windoContainer_createWindow_WEFF-585_(WSQ-3939)_sub1_auto.xml", "page001", "P0001", "existWindow", "","","","","wframe")
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_subWindow0_wframe_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') != 'undefined'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
